/**
 * useCustomers — Data fetching hook for the customer management list.
 *
 * Handles:
 * - Initial data load via GET /api/customers (paginated)
 * - Debounced search filtering across name, email, phone fields
 * - Pagination state management (25 per page by default)
 * - Loading and error states
 */

import { useState, useEffect, useCallback, useRef } from 'react'
import { fetchCustomers } from '../api.js'
import type { CustomerDetail, CustomerPaginatedResponse } from '../types.js'

// ---------------------------------------------------------------------------
// Constants
// ---------------------------------------------------------------------------

const DEFAULT_PAGE_SIZE = 25
const SEARCH_DEBOUNCE_MS = 300

// ---------------------------------------------------------------------------
// Hook State & Actions Interfaces
// ---------------------------------------------------------------------------

interface UseCustomersState {
  /** Paginated customer data */
  customers: CustomerDetail[]
  /** Total number of matching customers (for pagination) */
  totalItems: number
  /** Current page number (1-indexed) */
  currentPage: number
  /** Items per page */
  pageSize: number
  /** Total pages based on current search results */
  totalPages: number
  /** Current search term */
  searchTerm: string
  /** Whether data is currently being fetched */
  isLoading: boolean
  /** Error message from failed API calls, or null */
  error: string | null
}

interface UseCustomersActions {
  /** Set the search term (triggers debounced fetch) */
  setSearchTerm: (term: string) => void
  /** Navigate to a specific page */
  goToPage: (page: number) => void
  /** Reset pagination to page 1 and refetch */
  refresh: () => void
}

export type UseCustomersResult = UseCustomersState & UseCustomersActions

// ---------------------------------------------------------------------------
// Hook Implementation
// ---------------------------------------------------------------------------

/**
 * Custom hook for fetching and managing the customer list.
 *
 * Provides paginated results with debounced search filtering.
 */
export function useCustomers(): UseCustomersResult {
  const [customers, setCustomers] = useState<CustomerDetail[]>([])
  const [totalItems, setTotalItems] = useState(0)
  const [currentPage, setCurrentPage] = useState(1)
  const [pageSize] = useState(DEFAULT_PAGE_SIZE)
  const [searchTerm, setSearchTermState] = useState('')
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  // Ref for debounce timer
  const searchTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  // Debounced search term — actual value used in API calls
  const [debouncedSearchTerm, setDebouncedSearchTerm] = useState('')

  // -----------------------------------------------------------------------
  // Data fetching
  // -----------------------------------------------------------------------

  const fetchCustomerData = useCallback(async () => {
    setIsLoading(true)
    setError(null)

    try {
      const response: CustomerPaginatedResponse = await fetchCustomers({
        search: debouncedSearchTerm || undefined,
        page: currentPage,
        pageSize,
      })

      setCustomers(response.customers)
      setTotalItems(response.totalItems)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to load customers'
      setError(message)
      setCustomers([])
      setTotalItems(0)
    } finally {
      setIsLoading(false)
    }
  }, [debouncedSearchTerm, currentPage, pageSize])

  // -----------------------------------------------------------------------
  // Search debouncing
  // -----------------------------------------------------------------------

  const setSearchTerm = useCallback((term: string) => {
    setSearchTermState(term)

    // Clear existing timer
    if (searchTimerRef.current) {
      clearTimeout(searchTimerRef.current)
    }

    // Set new debounce timer
    searchTimerRef.current = setTimeout(() => {
      setDebouncedSearchTerm(term)
      // Reset to page 1 when search changes
      setCurrentPage(1)
    }, SEARCH_DEBOUNCE_MS)
  }, [])

  // -----------------------------------------------------------------------
  // Pagination
  // -----------------------------------------------------------------------

  const goToPage = useCallback((page: number) => {
    setCurrentPage(page)
  }, [])

  const refresh = useCallback(() => {
    fetchCustomerData()
  }, [fetchCustomerData])

  // -----------------------------------------------------------------------
  // Derived state
  // -----------------------------------------------------------------------

  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize))

  // -----------------------------------------------------------------------
  // Effects
  // -----------------------------------------------------------------------

  // Fetch data when search term or page changes
  useEffect(() => {
    fetchCustomerData()
  }, [fetchCustomerData])

  // Cleanup debounce timer on unmount
  useEffect(() => {
    return () => {
      if (searchTimerRef.current) {
        clearTimeout(searchTimerRef.current)
      }
    }
  }, [])

  // -----------------------------------------------------------------------
  // Return
  // -----------------------------------------------------------------------

  return {
    customers,
    totalItems,
    currentPage,
    pageSize,
    totalPages,
    searchTerm,
    isLoading,
    error,
    setSearchTerm,
    goToPage,
    refresh,
  }
}

